BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Section 501(h) expenditure test election lobbying limit
(3, 'Tax-Exempt Organizations', 'Riverdale Education Alliance, a 501(c)(3) with exempt purpose expenditures of $800,000, makes the Section 501(h) election. Under the expenditure test, what is the maximum amount the organization may spend on lobbying activities without jeopardizing its exempt status?', '["$100,000", "$120,000", "$145,000", "$160,000"]'::jsonb, 2, 'Under Section 501(h), the lobbying nontaxable amount is calculated on a sliding scale: 20% of the first $500,000 of exempt purpose expenditures ($100,000) plus 15% of the next $300,000 ($45,000), totaling $145,000. Option D ($160,000) incorrectly applies a flat 20% rate to the entire $800,000, ignoring the graduated scale that reduces the percentage as expenditures increase.', 'medium', 2),

-- Q2: easy / L1 — Dissolution clause requirement
(3, 'Tax-Exempt Organizations', 'What does the dissolution clause require for a Section 501(c)(3) organization?', '["Upon dissolution, remaining assets must be distributed to another exempt organization or the government", "Upon dissolution, remaining assets must be distributed equally among all board members", "Upon dissolution, remaining assets must be returned to the original donors", "Upon dissolution, remaining assets must be held in escrow for five years"]'::jsonb, 0, 'Under the organizational test for Section 501(c)(3), the governing documents must include a dissolution clause providing that upon dissolution, remaining assets are distributed to another 501(c)(3) organization or to the government for a public purpose. Option C is incorrect because there is no requirement to return assets to donors; the clause ensures assets continue serving exempt purposes.', 'easy', 1),

-- Q3: medium / L3 — Supporting organization classification under Section 509(a)(3)
(3, 'Tax-Exempt Organizations', 'Keystone Administrative Services is organized and operated exclusively to handle accounting, fundraising, and facility management for three local 501(c)(3) homeless shelters. Keystone does not solicit contributions from the general public. Under Section 509(a)(3), how is Keystone classified?', '["A private foundation subject to Section 4940–4945 excise taxes", "A supporting organization classified as a public charity", "A private operating foundation exempt from distribution requirements", "A social welfare organization under Section 501(c)(4)"]'::jsonb, 1, 'Under Section 509(a)(3), an organization operated exclusively to support one or more public charities qualifies as a supporting organization and is therefore classified as a public charity, avoiding private foundation status. Keystone meets this test by exclusively supporting three 501(c)(3) shelters. Option A is incorrect because supporting organizations are specifically excluded from private foundation classification under Section 509(a).', 'medium', 3),

-- Q4: medium / L3 — Controlled entity payments treated as UBIT
(3, 'Tax-Exempt Organizations', 'Hope Medical Foundation, a 501(c)(3) hospital, owns 90% of MedServices LLC, a taxable subsidiary. MedServices pays $200,000 in annual rent to Hope for office space, but comparable market rent is $150,000. How is the $200,000 rental payment treated for UBIT purposes?', '["The entire $200,000 is excluded as passive rental income from real property", "The entire $200,000 is included in Hope''s unrelated business taxable income", "The $150,000 fair market value portion is included in unrelated business taxable income", "The $50,000 excess over fair market value is included in Hope''s unrelated business taxable income"]'::jsonb, 3, 'Under IRC Section 512(b)(13), rent received from a controlled entity (80%+ ownership) is treated as UBIT to the extent it exceeds fair market value. Since Hope owns 90% of MedServices, only the $50,000 excess ($200,000 minus $150,000 FMV) is UBIT. Option A is incorrect because the passive income exclusion for real property rents does not fully apply when the payor is a controlled subsidiary.', 'medium', 3),

-- Q5: medium / L3 — Personal property rents vs real property rents in UBIT
(3, 'Tax-Exempt Organizations', 'Lakeside Arts Center, a 501(c)(3), leases its gallery building along with specialized display equipment to a commercial tenant. The total annual rent is $120,000, of which $30,000 (25%) is attributable to the personal property. How is this rental income treated under the UBIT rules?', '["The entire $120,000 is excluded as passive rental income from real property", "The entire $120,000 is included in UBIT because the lease bundles real and personal property", "$30,000 attributable to personal property is included in UBIT while $90,000 from real property is excluded", "Only $12,000 is included in UBIT as the standard 10% personal property threshold amount"]'::jsonb, 2, 'Under IRC Section 512(b)(3), rents from real property are generally excluded from UBIT, but rents from personal property are included unless incidental (less than 10% of total rents under the lease). Here, 25% of rent is from personal property, exceeding the 10% threshold, so the $30,000 personal property portion is UBIT while the $90,000 real property portion remains excluded. Option A is incorrect because personal property rents above 10% are not treated as incidental.', 'medium', 3),

-- Q6: medium / L3 — Convenience exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Oakdale Community Hospital, a 501(c)(3), operates a cafeteria in its lobby that serves meals to patients, visitors, and hospital employees during regular hours. The cafeteria earns $175,000 in annual net income. The controller must determine whether the cafeteria income is subject to UBIT. Which analysis is correct?', '["The income is excluded from UBIT under the convenience exclusion because the cafeteria primarily serves patients, visitors, and employees of the hospital", "The income is subject to UBIT because food service is not related to the hospital''s medical exempt purpose", "The income is excluded only if the cafeteria is staffed entirely by unpaid volunteers", "The income is subject to UBIT unless the cafeteria operates at a financial loss"]'::jsonb, 0, 'Under IRC Section 513(a)(2), income from a trade or business carried on primarily for the convenience of the organization''s members, students, patients, or employees is excluded from UBIT. A hospital cafeteria serving patients, visitors, and staff qualifies for this convenience exclusion. Option B is incorrect because the convenience exclusion applies regardless of whether the activity relates directly to the exempt purpose.', 'medium', 3),

-- Q7: medium / L3 — Research exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'State University, a 501(c)(3), receives $400,000 from a private pharmaceutical company to conduct clinical drug trials. The university publishes all research results in peer-reviewed journals available to the public. Is the $400,000 subject to UBIT?', '["Yes, because the research is funded by a private for-profit company", "Yes, because clinical drug trials are a commercial activity regularly carried on", "No, because all university research income is automatically exempt from UBIT", "No, because the research results are freely available to the public, qualifying for the research exclusion under Section 512(b)(9)"]'::jsonb, 3, 'Under IRC Section 512(b)(7)–(9), research performed by a college or university is excluded from UBIT when the results are freely available to the general public. The funding source (private company) does not disqualify the exclusion. Option A is incorrect because the research exclusion focuses on public availability of results, not on whether the funder is for-profit or nonprofit.', 'medium', 3),

-- Q8: easy / L1 — Form 990-N e-Postcard threshold
(3, 'Tax-Exempt Organizations', 'Which tax-exempt organizations are eligible to file Form 990-N (e-Postcard) instead of a full Form 990?', '["Organizations with gross receipts under $200,000 and total assets under $500,000", "Organizations with annual gross receipts normally $50,000 or less", "Organizations with annual gross receipts under $100,000 regardless of asset size", "All organizations that have been tax-exempt for fewer than three years"]'::jsonb, 1, 'Under IRC Section 6033(i), tax-exempt organizations with annual gross receipts normally $50,000 or less may file Form 990-N (e-Postcard), an electronic notice requiring only basic information such as name, address, and EIN. Option A describes the threshold for Form 990-EZ, not Form 990-N. Organizations exceeding $50,000 in gross receipts must file Form 990-EZ or full Form 990.', 'easy', 1),

-- Q9: medium / L2 — Filing deadline and Form 8868 extension
(3, 'Tax-Exempt Organizations', 'Bright Futures Foundation, a calendar-year 501(c)(3), needs additional time to prepare its Form 990 for the 2025 tax year ending December 31. What is the original filing deadline, and how long of an extension is available using Form 8868?', '["May 15, 2026, with an automatic six-month extension available through November 15, 2026", "April 15, 2026, with an automatic three-month extension available through July 15, 2026", "March 15, 2026, with an automatic six-month extension available through September 15, 2026", "June 15, 2026, with an automatic three-month extension available through September 15, 2026"]'::jsonb, 0, 'Under IRC Section 6033, Form 990 is due on the 15th day of the 5th month after the organization''s fiscal year-end. For a calendar-year organization, the deadline is May 15. Form 8868 provides an automatic six-month extension, moving the deadline to November 15. Option B is incorrect because the April 15 deadline applies to individual income tax returns, not to tax-exempt organization information returns.', 'medium', 2),

-- Q10: hard / L3 — Failure-to-file penalty calculation
(3, 'Tax-Exempt Organizations', 'Coastal Relief Network, a 501(c)(3) with annual gross receipts of $400,000, files its Form 990 sixty days late without reasonable cause. Under IRC Section 6652(c), the penalty is $20 per day for each day the return is late. What is the total penalty for the late filing?', '["$600", "$10,500", "$20,000", "$1,200"]'::jsonb, 3, 'Under Section 6652(c)(1)(A), the penalty for late filing of Form 990 is $20 per day for each day the return is late, up to the lesser of $10,500 or 5% of gross receipts. Here, $20 × 60 days = $1,200. The cap is the lesser of $10,500 or $20,000 (5% × $400,000), so the cap is $10,500. Since $1,200 is below the cap, the full penalty applies. Option B ($10,500) is the maximum cap, not the actual penalty owed.', 'hard', 3),

-- Q11: medium / L2 — Schedule J compensation disclosure
(3, 'Tax-Exempt Organizations', 'Pinnacle Health Foundation, a 501(c)(3) required to file Form 990, pays its CEO $350,000 and two vice presidents $200,000 each. On which Form 990 schedule must the organization report detailed compensation information for these officers?', '["Schedule A — Public Charity Status and Public Support", "Schedule B — Schedule of Contributors", "Schedule J — Compensation Information", "Schedule O — Supplemental Information"]'::jsonb, 2, 'Schedule J of Form 990 requires detailed reporting of compensation for officers, directors, trustees, key employees, and highest-compensated employees. This includes base pay, bonuses, deferred compensation, and nontaxable benefits. Option A (Schedule A) is used for public charity status and public support calculations, not compensation disclosure. Schedule B reports contributor information and is confidential.', 'medium', 2),

-- Q12: easy / L1 — Private inurement prohibition
(3, 'Tax-Exempt Organizations', 'Under Section 501(c)(3), what does the private inurement prohibition prevent?', '["The organization from earning any income from business activities", "Net earnings of the organization from benefiting any private shareholder or individual who is an insider", "The organization from paying reasonable compensation to its employees", "The organization from investing its surplus funds in the stock market"]'::jsonb, 1, 'Under IRC Section 501(c)(3), no part of the net earnings of a tax-exempt organization may inure to the benefit of any private shareholder or individual, meaning insiders such as founders, officers, directors, and persons with substantial influence. Option C is incorrect because paying reasonable compensation to employees is permitted; only excessive or unreasonable payments to insiders violate the prohibition.', 'easy', 1),

-- Q13: medium / L2 — One-third public support test under Section 509(a)(1)
(3, 'Tax-Exempt Organizations', 'Helping Hands Alliance, a 501(c)(3), received total support of $900,000 over the past four years: $350,000 from government grants, $250,000 from numerous small public contributions, and $300,000 from investment income. Under the one-third support test of Section 509(a)(1), does Helping Hands qualify as a public charity?', '["Yes, because $600,000 in government and public support exceeds the one-third threshold of $300,000", "No, because investment income of $300,000 exceeds the one-third threshold", "Yes, but only if the organization also passes a separate facts-and-circumstances test", "No, because government grants are not included in the public support computation"]'::jsonb, 0, 'Under Section 509(a)(1), an organization qualifies as a public charity if it receives at least one-third of its total support from governmental units and the general public. Here, $600,000 ($350,000 + $250,000) out of $900,000 equals 67%, well above the one-third threshold. Option D is incorrect because government grants are specifically included in the public support numerator under the one-third test.', 'medium', 2),

-- Q14: medium / L3 — Section 4941 additional tax for uncorrected self-dealing
(3, 'Tax-Exempt Organizations', 'Hartford Family Foundation, a private foundation, leases office space to its founder at below-market rent. The IRS imposes the initial 10% excise tax on the self-dealer under Section 4941. The founder refuses to correct the transaction within the taxable period. What additional tax is imposed on the self-dealer for failure to correct?', '["25% of the amount involved", "100% of the amount involved", "50% of the amount involved", "200% of the amount involved"]'::jsonb, 3, 'Under IRC Section 4941(b), if a self-dealing transaction is not corrected within the taxable period, an additional excise tax of 200% of the amount involved is imposed on the self-dealer. This steep additional tax is designed to compel prompt correction. Option A (25%) is incorrect because 25% is the initial tax rate under Section 4958 for excess benefit transactions, not the correction-period penalty for self-dealing.', 'medium', 3),

-- Q15: medium / L3 — Section 4945 taxable expenditure for grant without expenditure responsibility
(3, 'Tax-Exempt Organizations', 'Dawson Heritage Foundation, a private foundation, makes a $100,000 grant to a nonprofit that is not a 501(c)(3) organization. The foundation does not exercise expenditure responsibility over the grant or require charitable use of the funds. Under Section 4945, what is the consequence?', '["The grant is automatically treated as a qualifying distribution with no penalty", "The grant is a taxable expenditure subject to a 20% initial excise tax on the foundation", "The grant triggers the self-dealing rules under Section 4941", "The foundation loses its tax-exempt status immediately upon making the grant"]'::jsonb, 1, 'Under IRC Section 4945(d)(4), a grant by a private foundation to an organization that is not a 501(c)(3) is a taxable expenditure unless the foundation exercises expenditure responsibility to ensure the funds are used for charitable purposes. The initial excise tax is 20% of the expenditure amount. Option A is incorrect because grants to non-charities without expenditure responsibility do not qualify as permissible distributions.', 'medium', 3),

-- Q16: hard / L4 — Private benefit vs private inurement distinction
(3, 'Tax-Exempt Organizations', 'Community Education Partners, a 501(c)(3) tutoring nonprofit, hires an outside marketing consultant — who has no governance role or insider status — at $300,000 per year, triple the market rate. The consultant was selected by the executive director without board approval. Separately, the executive director receives a $50,000 no-interest personal loan from the organization. Evaluate which violation doctrine applies to each transaction.', '["Both transactions constitute private inurement because they involve use of organization funds", "Both transactions constitute excessive private benefit because they exceed fair market value", "The consultant arrangement is excessive private benefit to an outsider, while the personal loan to the executive director is private inurement by an insider", "The consultant arrangement triggers Section 4958 intermediate sanctions, while the personal loan is permissible as a de minimis fringe benefit"]'::jsonb, 2, 'Under IRC Section 501(c)(3), private inurement applies specifically to insiders (founders, officers, directors, and persons with substantial influence), while the private benefit doctrine is broader and covers outsiders. The consultant is an outsider receiving excessive private benefit. The executive director is an insider, so the no-interest loan constitutes private inurement. Option A is incorrect because private inurement requires insider status, which the consultant lacks.', 'hard', 4),

-- Q17: easy / L1 — Bingo game exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Under Section 513, which type of gaming activity is specifically excluded from unrelated business income tax?', '["Bingo games conducted legally where commercial bingo is not ordinarily carried out in the jurisdiction", "Casino nights organized to raise funds for the organization''s exempt purpose", "Raffles and sweepstakes conducted entirely by paid staff", "Online poker tournaments that generate income for charitable programs"]'::jsonb, 0, 'Under IRC Section 513(f), bingo games are specifically excluded from UBIT when they are conducted legally and commercial bingo is not regularly carried on in the same jurisdiction. This is a narrow statutory exclusion for bingo only. Option B is incorrect because casino nights, raffles, and other gaming activities do not receive the same specific statutory exclusion as bingo.', 'easy', 1),

-- Q18: hard / L4 — Rebuttable presumption of reasonableness conditions
(3, 'Tax-Exempt Organizations', 'Metro Arts Council, a 501(c)(3), promotes its artistic director to CEO with total compensation of $475,000. The board chair — who is the new CEO''s spouse — participates in the approval vote. Two other board members rely on a salary survey of similar-sized arts organizations and document their analysis in the minutes. Evaluate whether the rebuttable presumption of reasonableness under Section 4958 applies.', '["The presumption applies because two independent board members approved the compensation with supporting data", "The presumption applies because the salary survey constitutes appropriate comparability data regardless of board composition", "The presumption does not apply because $475,000 automatically exceeds reasonable compensation for an arts organization", "The presumption does not apply because the board chair''s spousal relationship compromises the independence requirement, even though comparability data and documentation exist"]'::jsonb, 3, 'Under Section 4958, the rebuttable presumption of reasonableness requires all three conditions: (1) approval by an independent board or committee, (2) reliance on appropriate comparability data, and (3) contemporaneous documentation. The board chair''s spousal relationship to the CEO creates a conflict of interest that compromises independence, defeating the presumption even though conditions (2) and (3) are met. Option A is incorrect because the conflicted chair''s participation taints the approval process.', 'hard', 4),

-- Q19: medium / L2 — Gross receipts test under Section 509(a)(2)
(3, 'Tax-Exempt Organizations', 'Mountain View Center, a 501(c)(3), receives total support of $500,000: $180,000 from program service fees related to its exempt function, $50,000 from membership dues, $70,000 from public donations, and $200,000 from investment income. Under Section 509(a)(2), which support sources count toward the one-third gross receipts test for public charity classification?', '["Only public donations and membership dues totaling $120,000", "Program service fees, membership dues, and public donations totaling $300,000", "Program service fees and investment income totaling $380,000", "All $500,000 because every source of revenue counts toward the gross receipts test"]'::jsonb, 1, 'Under Section 509(a)(2), the one-third support test counts contributions, membership fees, and gross receipts from activities related to exempt functions. Program service fees ($180,000), membership dues ($50,000), and public donations ($70,000) total $300,000, which is 60% of $500,000. Investment income is excluded from the numerator. Option C is incorrect because passive investment income does not count toward the gross receipts support test.', 'medium', 2),

-- Q20: medium / L2 — Automatic public charity classification for churches
(3, 'Tax-Exempt Organizations', 'Calvary Community Church operates solely through member donations averaging $80,000 per year and has never applied separately for public charity status. A new board member questions whether the church qualifies as a public charity or is classified as a private foundation. How is the church classified?', '["As a private foundation because it has not filed for separate public charity status", "As a private foundation because it receives support primarily from members rather than the general public", "As a public charity automatically because churches are classified as public charities regardless of their funding sources", "As a public charity only if its annual gross receipts exceed $200,000"]'::jsonb, 2, 'Under IRC Section 509(a)(1) and Section 170(b)(1)(A)(i), churches are automatically classified as public charities without needing to meet the one-third public support test or any other financial threshold. This classification applies regardless of funding sources or amounts. Option B is incorrect because the source of a church''s support is irrelevant to its automatic public charity classification.', 'medium', 2),

-- Q21: easy / L1 — Form 990-PF filing requirement for private foundations
(3, 'Tax-Exempt Organizations', 'Which annual information return must all private foundations file regardless of their size or income level?', '["Form 990-PF", "Form 990", "Form 990-EZ", "Form 990-N"]'::jsonb, 0, 'Under IRC Section 6033, all private foundations must file Form 990-PF annually, regardless of their gross receipts or total assets. This form includes detailed reporting of grants, investments, and excise tax computations under Sections 4940–4945. Option B (Form 990) and Option C (Form 990-EZ) are filed by public charities based on size thresholds, not by private foundations.', 'easy', 1),

-- Q22: easy / L2 — NOL deduction computed using only UBI items
(3, 'Tax-Exempt Organizations', 'Golden Heritage Society, a 501(c)(3), has $15,000 in unrelated business taxable income in 2025 and a $5,000 net operating loss from unrelated business activities carried forward from 2024. How is the prior-year NOL applied?', '["The NOL cannot be carried forward because tax-exempt organizations are not permitted to claim NOL deductions", "The $5,000 NOL is deducted against all income including exempt purpose income and investment income", "The NOL is limited to 50% of the 2025 UBI reducing taxable income to $12,500", "The $5,000 NOL is deducted against the 2025 UBI reducing taxable income to $10,000 because NOLs for UBIT are computed using only unrelated business income items"]'::jsonb, 3, 'Under IRC Section 512(b)(6), a net operating loss deduction is allowed for UBIT purposes, but it is computed using only items of unrelated business income and deductions. The $5,000 NOL from 2024 unrelated business activities reduces 2025 UBI from $15,000 to $10,000. Option A is incorrect because tax-exempt organizations are specifically permitted NOL deductions for their unrelated business income.', 'easy', 2),

-- Q23: easy / L1 — Exempt purposes under Section 501(c)(3)
(3, 'Tax-Exempt Organizations', 'Which of the following is an exempt purpose recognized under Section 501(c)(3)?', '["Promotion of political candidates for public office", "Prevention of cruelty to children or animals", "Providing financial returns to members and shareholders", "Operating social clubs for recreational purposes"]'::jsonb, 1, 'Section 501(c)(3) recognizes specific exempt purposes including religious, charitable, scientific, educational, literary, testing for public safety, fostering amateur sports competition, and prevention of cruelty to children or animals. Option A is incorrect because political campaign activity is absolutely prohibited for 501(c)(3) organizations. Social clubs operate under Section 501(c)(7), not 501(c)(3).', 'easy', 1),

-- Q24: medium / L2 — Schedule A for public charity status reporting
(3, 'Tax-Exempt Organizations', 'Clearwater Environmental Trust, a 501(c)(3) public charity, completes its annual Form 990. The executive director asks which schedule demonstrates the organization''s continued public charity qualification and public support calculations. Which Form 990 schedule serves this purpose?', '["Schedule B — Schedule of Contributors", "Schedule D — Supplemental Financial Statements", "Schedule A — Public Charity Status and Public Support", "Schedule O — Supplemental Information"]'::jsonb, 2, 'Schedule A of Form 990 is specifically designed to report an organization''s public charity status and compute the public support percentage under Section 509(a)(1) or 509(a)(2). It documents the basis for public charity classification. Option A (Schedule B) reports contributor information and is kept confidential; it does not demonstrate public charity qualification.', 'medium', 2),

-- Q25: hard / L4 — Total excise taxes on uncorrected excess benefit transaction
(3, 'Tax-Exempt Organizations', 'Meridian Youth Foundation, a 501(c)(3), pays its program director — a disqualified person under Section 4958 — a $600,000 salary when comparable compensation is $350,000. The excess benefit is $250,000. The director fails to return the excess amount within the taxable period. Analyze the total excise taxes imposed on the program director under Section 4958.', '["$62,500 — only the initial 25% tax on the $250,000 excess benefit", "$500,000 — only the 200% correction tax on the $250,000 excess benefit", "$312,500 — a combined 125% tax on the $250,000 excess benefit", "$562,500 — the initial 25% tax ($62,500) plus the 200% additional tax ($500,000) for failure to correct"]'::jsonb, 3, 'Under Section 4958, the initial excise tax on a disqualified person is 25% of the excess benefit ($250,000 × 25% = $62,500). If not corrected within the taxable period, an additional 200% tax applies ($250,000 × 200% = $500,000). Total taxes on the director: $62,500 + $500,000 = $562,500. Option A is incorrect because it omits the substantial 200% additional tax imposed for failure to correct the excess benefit.', 'hard', 4),

-- Q26: hard / L4 — Interaction between debt-financed income and controlled entity rules
(3, 'Tax-Exempt Organizations', 'Apex Education Foundation, a 501(c)(3), owns 85% of TechCo LLC. TechCo pays Apex $100,000 in annual rent for a building Apex purchased with a mortgage. The average acquisition indebtedness is $600,000 and the average adjusted basis is $1,000,000. Fair market value rent is $80,000. Evaluate how the controlled entity rules and debt-financed income rules interact.', '["$68,000 total UBIT — $20,000 excess over FMV under controlled entity rules plus $48,000 debt-financed income (60% of the $80,000 FMV portion)", "$20,000 — only the amount exceeding fair market value under the controlled entity rules", "$60,000 — applying the 60% debt-to-basis ratio to the entire $100,000 payment", "$100,000 — all rent from a controlled subsidiary is automatically included in UBIT"]'::jsonb, 0, 'Under Section 512(b)(13), the $20,000 excess over FMV ($100,000 − $80,000) from the controlled entity is UBIT. The remaining $80,000 FMV portion would normally be excluded as real property rent, but under Section 514, the debt-financed percentage (60% = $600,000/$1,000,000) makes $48,000 of that amount UBIT. Total: $20,000 + $48,000 = $68,000. Option B is incorrect because it ignores the debt-financed income component on the FMV rental portion.', 'hard', 4),

-- Q27: medium / L2 — Section 4943 combined permitted holdings with disqualified persons
(3, 'Tax-Exempt Organizations', 'Crestview Family Foundation, a private foundation, owns 12% of the voting stock of Henderson Industries. The foundation''s disqualified persons collectively own 15% of Henderson''s voting stock. Under Section 4943, the combined permitted holdings are generally 20%. Does the foundation have excess business holdings?', '["No, because the foundation''s own 12% holding does not exceed 20%", "Yes, the combined 27% exceeds the 20% limit, resulting in 7% excess business holdings subject to excise tax", "Yes, but only the foundation''s 12% holding is subject to excise tax", "No, because the 20% limit applies separately to the foundation and its disqualified persons"]'::jsonb, 1, 'Under IRC Section 4943, a private foundation and its disqualified persons may not together hold more than 20% of the voting stock of a business enterprise. Here, 12% + 15% = 27%, creating 7% excess business holdings subject to a 10% initial excise tax. Option D is incorrect because Section 4943 applies the 20% limit to the combined holdings of the foundation and all disqualified persons, not separately.', 'medium', 2),

-- Q28: hard / L4 — Private foundation lobbying as taxable expenditure under Section 4945
(3, 'Tax-Exempt Organizations', 'Henderson Charitable Trust, a private foundation, spends $50,000 lobbying Congress to support education funding legislation. The foundation''s board believes the expenditure furthers its educational exempt purpose. Unlike public charities that may lobby within limits, evaluate how Section 4945 treats this lobbying expenditure by a private foundation.', '["The expenditure is permitted because it supports the foundation''s educational exempt purpose", "The expenditure is subject to the same substantial-part test that applies to public charities", "The $50,000 is a taxable expenditure subject to a 20% initial excise tax ($10,000) because private foundations are prohibited from lobbying under Section 4945", "The expenditure triggers automatic revocation of the foundation''s tax-exempt status"]'::jsonb, 2, 'Under IRC Section 4945(d)(1), any amount paid by a private foundation to influence legislation is a taxable expenditure, subject to a 20% initial excise tax on the foundation ($50,000 × 20% = $10,000). Unlike public charities, private foundations may not lobby at all. Option B is incorrect because the substantial-part test and the Section 501(h) expenditure test apply only to public charities, not to private foundations.', 'hard', 4),

-- Q29: easy / L1 — Operational test for Section 501(c)(3)
(3, 'Tax-Exempt Organizations', 'What is the operational test for Section 501(c)(3) tax-exempt status?', '["The organization must generate at least 50% of revenue from charitable donations", "The organization must have at least five independent board members", "The organization must be incorporated in the state where it conducts primary activities", "The organization must be operated primarily to accomplish one or more exempt purposes"]'::jsonb, 3, 'Under IRC Section 501(c)(3), the operational test requires that an organization be operated primarily for one or more exempt purposes, meaning it engages primarily in activities that accomplish those purposes. The test also prohibits private inurement and limits lobbying and political activity. Option A is incorrect because there is no specific revenue-source percentage requirement in the operational test.', 'easy', 1),

-- Q30: easy / L1 — Initial excise tax rate on excess benefit transactions
(3, 'Tax-Exempt Organizations', 'Under Section 4958, what is the initial excise tax rate imposed on a disqualified person who receives an excess benefit from a 501(c)(3) organization?', '["25% of the excess benefit", "10% of the excess benefit", "50% of the excess benefit", "100% of the excess benefit"]'::jsonb, 0, 'Under IRC Section 4958(a)(1), the initial excise tax on a disqualified person who participates in an excess benefit transaction is 25% of the excess benefit amount. This intermediate sanction allows the IRS to penalize the individual without revoking the organization''s exempt status. Option B (10%) is the tax rate on an organization manager who knowingly approves an excess benefit transaction, not the rate on the disqualified person.', 'easy', 1)
;

COMMIT;
